def winning_losing_states(n: int, allowed_moves: list[int]) -> list[bool]:
    # dp[i] = True if Winning State (N-pos), False if Losing State (P-pos)
    dp = [False] * (n + 1)
    for i in range(1, n + 1):
        for m in allowed_moves:
            if i >= m and not dp[i - m]:
                dp[i] = True
                break
    return dp

