def find_winning_move(heaps: list[int]) -> tuple[int, int] | None:
    s = 0
    for h in heaps:
        s ^= h
    if s == 0:
        return None  # No winning move possible (Losing State)
    for i, h in enumerate(heaps):
        if (h ^ s) < h:
            target_size = h ^ s
            return (i, target_size)  # Reduce heap i to target_size
    return None

