pair<int, int> findWinningMove(vector<int>& heaps) {
    int s = 0;
    for (int h : heaps) s ^= h;
    if (s == 0) return {-1, -1};
    for (size_t i = 0; i < heaps.size(); i++) {
        if ((heaps[i] ^ s) < heaps[i]) {
            return { (int)i, heaps[i] ^ s };
        }
    }
    return {-1, -1};
}

