def minimax(depth: int, node_idx: int, is_max: bool, scores: list[int], max_depth: int) -> int:
    if depth == max_depth:
        return scores[node_idx]
    if is_max:
        return max(minimax(depth + 1, node_idx * 2, False, scores, max_depth),
                   minimax(depth + 1, node_idx * 2 + 1, False, scores, max_depth))
    else:
        return min(minimax(depth + 1, node_idx * 2, True, scores, max_depth),
                   minimax(depth + 1, node_idx * 2 + 1, True, scores, max_depth))

