def minimax_alpha_beta(depth: int, node_idx: int, is_max: bool, scores: list[int], alpha: int, beta: int, max_depth: int) -> int:
    if depth == max_depth:
        return scores[node_idx]
    if is_max:
        best = float('-inf')
        for i in range(2):
            val = minimax_alpha_beta(depth + 1, node_idx * 2 + i, False, scores, alpha, beta, max_depth)
            best = max(best, val)
            alpha = max(alpha, best)
            if beta <= alpha:
                break  # Beta Pruning
        return best
    else:
        best = float('inf')
        for i in range(2):
            val = minimax_alpha_beta(depth + 1, node_idx * 2 + i, True, scores, alpha, beta, max_depth)
            best = min(best, val)
            beta = min(beta, best)
            if beta <= alpha:
                break  # Alpha Pruning
        return best

